        return this.rates.keys()
    }

    public func add_currency_rate(currency: String, rate: Float64): Bool {
        if this.rates.contains(currency) {
            return false
        }
        this.rates.add(currency, rate)
        return true
    }

    public func update_currency_rate(currency: String, new_rate: Float64): Bool {
        if not this.rates.contains(currency) {
            return false
        }
        this.rates.set(currency, new_rate)
        return true
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.math.round
import std.math.abs
import std.sort.sort

class DataStatistics {

    public func mean(data: ArrayList<Int64>): Float64 {
        let sum = 0
        for num in data {
            sum += num
        }
        let meanValue = Float64(sum) / Float64(data.size())
        return round(meanValue * 100) / 100
    }

    public func median(data: ArrayList<Int64>): Float64 {
        let sortedData = sort(data)
        let n = sortedData.size()
        if n % 2 == 0 {
            let middle = n // 2
            let medianValue = (Float64(sortedData.get(middle - 1)) + Float64(sortedData.get(middle))) / 2.0
            return round(medianValue * 100) / 100
        } else {
            let middle = n // 2
            return Float64(sortedData.get(middle))
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let counter = HashMap<Int64, Int64>()
        for num in data {
            if counter.contains(num) {
                counter.set(num, counter.get(num) + 1)
            } else {
                counter.set(num, 1)
            }
        }
        let maxCount = 0
        let modeList = ArrayList<Int64>()
        for (num, count) in counter {
            if count > maxCount {
                maxCount = count
                modeList.clear()
                modeList.add(num)
            } else if count == maxCount {
                modeList.add(num)
            }
        }
        return modeList
    }
}

