        for num in this.data {
            if num < min_val {
                min_val = num
            }
        }
        return min_val
    }

    public func get_max(): Float64 {
        let max_val = this.data[0]
        for num in this.data {
            if num > max_val {
                max_val = num
            }
        }
        return max_val
    }

    public func get_variance(): Float64 {
        let mean = self.get_sum() / this.data.size()
        let variance = 0.0
        for num in this.data {
            variance += (num - mean) * (num - mean)
        }
        variance /= this.data.size()
        return round(variance * 100) / 100
    }

    public func get_std_deviation(): Float64 {
        let variance = self.get_variance()
        let std_dev = sqrt(variance)
        return round(std_dev * 100) / 100
    }

    public func get_correlation(): Float64 {
        let n = this.data.size()
        if n <= 1 {
            return 1.0
        }
        let sum_x = self.get_sum()
        let sum_y = sum_x
        let sum_xy = 0.0
        let sum_x2 = 0.0
        let sum_y2 = 0.0
        for x in this.data {
            sum_xy += x * x
            sum_x2 += x * x
            sum_y2 += x * x
        }
        let numerator = sum_xy - (sum_x * sum_y) / n
        let denominator = sqrt((sum_x2 - (sum_x * sum_x) / n) * (sum_y2 - (sum_y * sum_y) / n))
        if denominator == 0.0 {
            return 1.0
        }
        return numerator / denominator
    }
}

import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs
import std.math.pi
import std.math.pow

class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size()
        let mean1 = data1.sum() / n
        let mean2 = data2.sum() / n

        let numerator = (0..n).map(i -> (data1[i] - mean1) * (data2[i] - mean2)).sum()
        let denominator = sqrt((0..n).map(i -> pow(data1[i] - mean1, 2)).sum()) * sqrt((0..n).map(i -> pow(data2[i] - mean2, 2)).sum())

        return denominator != 0 ? numerator / denominator : 0.0
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        let mean = data.sum() / n
        let variance = data.map(x -> pow(x - mean, 2)).sum() / n
        let std_deviation = sqrt(variance)

        let skewness = std_deviation != 0 ? (data.map(x -> pow(x - mean, 3)).sum() * n) / ((n - 1) * (n - 2) * pow(std_deviation, 3)) : 0.0

        return skewness
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        let mean = data.sum() / n
        let std_dev = sqrt(data.map(x -> pow(x - mean, 2)).sum() / n)

        if std_dev == 0 {
            return Float64.nan
        }

        let centered_data = data.map(x -> x - mean)
        let fourth_moment = centered_data.map(x -> pow(x, 4)).sum() / n

        let kurtosis_value = (fourth_moment / pow(std_dev, 4)) - 3

        return kurtosis_value
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        return data.map(x -> (1 / (sigma * sqrt(2 * pi))) * exp(-0.5 * pow((x - mu) / sigma, 2)))
    }
}

import std.collection.ArrayList

class DecryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        let plaintext: String = ""
        for char in ciphertext {
            if char.isalpha() {
                let ascii_offset: Int64 = char.isupper() ? 65 : 97
                let shifted_char: String = chr((ord(char) - ascii_offset - shift) % 26 + ascii_offset)
                plaintext += shifted_char
            } else {
                plaintext += char
            }
        }
        return plaintext
    }

    public func vigenere_decipher(ciphertext: String): String {
        let decrypted_text: String = ""
        let key_index: Int64 = 0
        for char in ciphertext {
            if char.isalpha() {
                let shift: Int64 = ord(this.key[key_index % len(this.key)].lower()) - ord('a')
                let decrypted_char: String = chr((ord(char.lower()) - ord('a') - shift) % 26 + ord('a'))
                decrypted_text += char.isupper() ? decrypted_char.upper() : decrypted_char
                key_index += 1
            } else {
                decrypted_text += char
            }
        }
        return decrypted_text
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        let fence: ArrayList[ArrayList[String]] = ArrayList()
        for _ in 0..<rails {
            let row: ArrayList[String] = ArrayList()
            for _ in 0..<len(encrypted_text) {
                row.add("\n")
            }
            fence.add(row)
        }

        let direction: Int64 = -1
        let mut row: Int64 = 0
        let mut col: Int64 = 0

        for _ in 0..<len(encrypted_text) {
            if row == 0 or row == rails - 1 {
                direction *= -1
            }
            fence[row][col] = ""
            col += 1
            row += direction
        }

        let mut index: Int64 = 0
        for i in 0..<rails {
            for j in 0..<len(encrypted_text) {
                if fence[i][j] == "" {
                    fence[i][j] = encrypted_text[index]
                    index += 1
                }
            }
        }

        let plain_text: String = ""
        let mut row: Int64 = 0
        let mut col: Int64 = 0
        let mut direction: Int64 = -1
        for _ in 0..<len(encrypted_text) {
            if row == 0 or row == rails - 1 {
                direction *= -1
            }
            plain_text += fence[row][col]
            col += 1
            row += direction
        }

        return plain_text
    }
}

