import std.collection.ArrayList

class EightPuzzle {

    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 2, 3]), ArrayList<Int64>([4, 5, 6]), ArrayList<Int64>([7, 8, 0])])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        for i in 0..<3 {
            for j in 0..<3 {
                if state[i][j] == 0 {
                    return (i.toInt64(), j.toInt64())
                }
            }
        }
        return (-1.toInt64(), -1.toInt64())
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        let (i, j) = self.find_blank(state)
        let new_state = ArrayList<ArrayList<Int64>>()
        for row in state {
            new_state.append(ArrayList<Int64>(row))
        }

        if direction == "up" {
            new_state[i][j] = new_state[i - 1][j]
            new_state[i - 1][j] = 0.toInt64()
        } elif direction == "down" {
            new_state[i][j] = new_state[i + 1][j]
            new_state[i + 1][j] = 0.toInt64()
        } elif direction == "left" {
            new_state[i][j] = new_state[i][j - 1]
            new_state[i][j - 1] = 0.toInt64()
        } elif direction == "right" {
            new_state[i][j] = new_state[i][j + 1]
            new_state[i][j + 1] = 0.toInt64()
        }

        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let moves = ArrayList<String>()
        let (i, j) = self.find_blank(state)

        if i > 0 {
            moves.append("up")
        }
        if i < 2 {
            moves.append("down")
        }
        if j > 0 {
            moves.append("left")
        }
        if j < 2 {
            moves.append("right")
        }

        return moves
    }

    public func solve(): ArrayList<String> {
        let open_list = ArrayList<(ArrayList<ArrayList<Int64>>, ArrayList<String>)>()
        open_list.append((self.initial_state, ArrayList<String>()))
        let closed_list = ArrayList<ArrayList<ArrayList<Int64>>>()

        while !open_list.isEmpty() {
            let (current_state, path) = open_list.removeAt(0)
            closed_list.append(current_state)

            if current_state == self.goal_state {
                return path
            }

            for move in self.get_possible_moves(current_state) {
                let new_state = self.move(current_state, move)
                if !closed_list.contains(new_state) {
                    let new_path = ArrayList<String>(path)
                    new_path.append(move)
                    open_list.append((new_state, new_path))
                }
            }
        }

        return ArrayList<String>()
    }
}

import std.time.DateTime
import std.collection.ArrayList
import std.collection.HashMap

class EmailClient {

    let addr: String
    let capacity: Int64
    var inbox: ArrayList<HashMap<String, Any>>

    public init(addr: String, capacity: Int64) {
        this.addr = addr
        this.capacity = capacity
        this.inbox = ArrayList<HashMap<String, Any>>()
    }

    public func send_to(recv: EmailClient, content: String, size: Int64): Bool {
        if !recv.is_full_with_one_more_email(size) {
            let timestamp = DateTime.now().format("yyyy-MM-dd HH:mm:ss")
            let email = HashMap<String, Any>([
                "sender": this.addr,
                "receiver": recv.addr,
                "content": content,
                "size": size,
                "time": timestamp,
                "state": "unread"
            ])
            recv.inbox.add(email)
            return true
        } else {
            this.clear_inbox(size)
            return false
        }
    }

    public func fetch(): HashMap<String, Any> {
        if this.inbox.size() == 0 {
            return null
        }
        for i in 0..<this.inbox.size() {
            if this.inbox.get(i)["state"] as String == "unread" {
                this.inbox.get(i)["state"] = "read"
                return this.inbox.get(i)
            }
        }
        return null
    }

    public func is_full_with_one_more_email(size: Int64): Bool {
        let occupied_size = this.get_occupied_size()
        return occupied_size + size > this.capacity
    }

    public func get_occupied_size(): Int64 {
        var occupied_size: Int64 = 0
        for email in this.inbox {
            occupied_size += email["size"] as Int64
        }
        return occupied_size
    }

    public func clear_inbox(size: Int64): Unit {
        if this.addr.length() == 0 {
            return
        }
        var freed_space: Int64 = 0
        while freed_space < size && this.inbox.size() > 0 {
            let email = this.inbox.get(0)
            freed_space += email["size"] as Int64
            this.inbox.remove(0)
        }
    }
}

import std.collection.ArrayList

class EncryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        let ciphertext = StringBuilder()
        for char in plaintext {
            if char.isAlpha() {
                let ascii_offset = char.isUpper() ? 65 : 97
                let shifted_char = ((char.codePoint() - ascii_offset + shift) % 26 + ascii_offset).toChar()
                ciphertext.append(shifted_char)
            } else {
                ciphertext.append(char)
            }
        }
        return ciphertext.toString()
    }

    public func vigenere_cipher(plain_text: String): String {
        let encrypted_text = StringBuilder()
        let mut key_index = 0
        for char in plain_text {
            if char.isAlpha() {
                let shift = key[key_index % key.length()].toLower().codePoint() - 'a'.codePoint()
                let encrypted_char = ((char.toLower().codePoint() - 'a'.codePoint() + shift) % 26 + 'a'.codePoint()).toChar()
                encrypted_text.append(char.isUpper() ? encrypted_char.toUpper() : encrypted_char)
                key_index += 1
            } else {
                encrypted_text.append(char)
            }
        }
        return encrypted_text.toString()
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        let fence = ArrayList<ArrayList<String>>()
        for i in 0..rails {
            fence.add(ArrayList<String>())
            for j in 0..plain_text.length() {
                fence[i].add("\n")
            }
        }
        let mut direction = -1
        let mut row = 0
        let mut col = 0

        for char in plain_text {
            if row == 0 || row == rails-1 {
                direction *= -1
            }
            fence[row][col] = char.toString()
            col += 1
            row += direction
        }

        let encrypted_text = StringBuilder()
        for i in 0..rails {
            for j in 0..plain_text.length() {
                if fence[i][j] != "\n" {
                    encrypted_text.append(fence[i][j])
                }
            }
        }
        return encrypted_text.toString()
    }
}

import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList
import std.collection.Deque

class ExpressionCalculator {

    let postfix_stack: Deque<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = Deque<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        self.prepare(self.transform(expression))

        let result_stack = Deque<String>()
        postfix_stack.reverse()

        while not postfix_stack.empty() {
            let current_op = postfix_stack.pop()
            if not self.is_operator(current_op) {
                let temp_op = current_op.replace("~", "-")
                result_stack.push(temp_op)
            } else {
                let second_value = result_stack.pop()
                let first_value = result_stack.pop()

                let temp_first = first_value.replace("~", "-")
                let temp_second = second_value.replace("~", "-")

                let temp_result = self._calculate(temp_first, temp_second, current_op)
                result_stack.push(temp_result.to_string())
            }
        }

        return eval(result_stack.join("*")).to_float64()
    }

    public func prepare(expression: String): Unit {
        let op_stack = Deque<String>([","])
        let arr = expression.to_char_array()
        let mut current_index = 0
        let mut count = 0

        for i in 0..arr.size() {
            let current_op = arr[i].to_string()
            if self.is_operator(current_op) {
                if count > 0 {
                    postfix_stack.push(arr.slice(current_index, current_index + count).join(""))
                }
                let peek_op = op_stack.peek()
                if current_op == ")" {
                    while op_stack.peek() != "(" {
                        postfix_stack.push(op_stack.pop())
                    }
                    op_stack.pop()
                } else {
                    while current_op != "(" and peek_op != "," and self.compare(current_op, peek_op) {
                        postfix_stack.push(op_stack.pop())
                        let peek_op = op_stack.peek()
                    }
                    op_stack.push(current_op)
                }
                count = 0
                current_index = i + 1
            } else {
                count += 1
            }
        }

        if count > 1 or (count == 1 and not self.is_operator(arr[current_index].to_string())) {
            postfix_stack.push(arr.slice(current_index, current_index + count).join(""))
        }

        while op_stack.peek() != "," {
            postfix_stack.push(op_stack.pop())
        }
    }

    public static func is_operator(c: String): Bool {
        return ["+", "-", "*", "/", "(", ")", "%"].contains(c)
    }

    public func compare(cur: String, peek: String): Bool {
        let mut temp_cur = cur
        let mut temp_peek = peek
        if temp_cur == "%" {
            temp_cur = "/"
        }
        if temp_peek == "%" {
            temp_peek = "/"
        }
        return operat_priority[temp_peek.to_char().to_int64() - 40] >= operat_priority[temp_cur.to_char().to_int64() - 40]
    }

    public static func _calculate(first_value: String, second_value: String, current_op: String): Decimal {
        let first = Decimal.parse(first_value)
        let second = Decimal.parse(second_value)
        if current_op == "+" {
            return first + second
        } elif current_op == "-" {
            return first - second
        } elif current_op == "*" {
            return first * second
        } elif current_op == "/" {
            return first / second
        } elif current_op == "%" {
            return first % second
        } else {
            raise ValueError("Unexpected operator: " + current_op)
        }
    }

    public static func transform(expression: String): String {
        let mut transformed = Regex.replace(expression, r"\s+", "")
        transformed = Regex.replace(transformed, r"=$", "")
        let arr = transformed.to_char_array()

        for i in 0..arr.size() {
            if arr[i] == '-' {
                if i == 0 {
                    arr[i] = '~'
                } else {
                    let prev_c = arr[i - 1]
                    if ["+", "-", "*", "/", "(", "E", "e"].contains(prev_c.to_string()) {
                        arr[i] = '~'
                    }
                }
            }
        }

        if arr.size() > 0 and arr[0] == '~' and (arr.size() > 1 and arr[1] == '(') {
            arr[0] = '-'
            return "0" + arr.join("")
        } else {
            return arr.join("")
        }
    }
}

import std.collection.ArrayList
