        let matching_jobs = ArrayList<JobListing>()
        for job in this.jobListings {
            let contains_title = job.job_title.lower().contains(criteria.lower())
            let contains_requirement = false
            for requirement in job.requirements {
                if requirement.lower().contains(criteria.lower()) {
                    contains_requirement = true
                    break
                }
            }
            if contains_title || contains_requirement {
                matching_jobs.append(job)
            }
        }
        return matching_jobs
    }

