        for skill in resume.skills {
            let found = false
            for requirement in requirements {
                if skill == requirement {
                    found = true
                    break
                }
            }
            if !found {
                return false
            }
        }
        return true
    }
}

import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        let dataMat = testData
        var P0 = 0.0
        for i in 0..<k {
            P0 += Float64(dataMat[i][i])
        }
        let xsum = ArrayList<Float64>()
        for row in dataMat {
            xsum.add(Float64(row.sum()))
        }
        let ysum = ArrayList<Float64>()
        for j in 0..<k {
            var colSum = 0.0
            for i in 0..<k {
                colSum += Float64(dataMat[i][j])
            }
            ysum.add(colSum)
        }
        let totalSum = xsum.sum()
        var Pe = 0.0
        for i in 0..<k {
            Pe += xsum[i] * ysum[i]
        }
        Pe /= totalSum * totalSum
        P0 /= totalSum
        return (P0 - Pe) / (1.0 - Pe)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        let dataMat = testData
        var sum = 0.0
        var P0 = 0.0
        for i in 0..<N {
            var temp = 0.0
            for j in 0..<k {
                sum += Float64(dataMat[i][j])
                temp += Float64(dataMat[i][j] * dataMat[i][j])
            }
            temp -= Float64(n)
            temp /= Float64((n - 1) * n)
            P0 += temp
        }
        P0 /= Float64(N)
        let ysum = ArrayList<Float64>()
        for j in 0..<k {
            var colSum = 0.0
            for i in 0..<N {
                colSum += Float64(dataMat[i][j])
            }
            ysum.add(colSum / sum)
        }
        var Pe = 0.0
        for val in ysum {
            Pe += val * val
        }
        return (P0 - Pe) / (1.0 - Pe)
    }
}

