import std.collection.ArrayList
import std.collection.HashSet
import std.random.Random

class MahjongConnect {

    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        let board = ArrayList<ArrayList<String>>()
        let random = Random()
        for (var i: Int64 = 0; i < BOARD_SIZE.get(0); i += 1) {
            let row = ArrayList<String>()
            for (var j: Int64 = 0; j < BOARD_SIZE.get(1); j += 1) {
                let icon = ICONS.get(random.nextInt(0, ICONS.size() - 1))
                row.add(icon)
            }
            board.add(row)
        }
        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2

        if !(0 <= x1 && x1 < BOARD_SIZE.get(0) && 0 <= y1 && y1 < BOARD_SIZE.get(1) && 0 <= x2 && x2 < BOARD_SIZE.get(0) && 0 <= y2 && y2 < BOARD_SIZE.get(1)) {
            return false
        }

        if pos1 == pos2 {
            return false
        }

        if board.get(x1).get(y1) != board.get(x2).get(y2) {
            return false
        }

        if !has_path(pos1, pos2) {
            return false
        }

        return true
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let visited = ArrayList<(Int64, Int64)>()
        let stack = ArrayList<(Int64, Int64)>()
        stack.add(pos1)

        while !stack.isEmpty() {
            let current_pos = stack.remove(stack.size() - 1)
            if current_pos == pos2 {
                return true
            }

            if contains(visited, current_pos) {
                continue
            }

            visited.add(current_pos)
            let (x, y) = current_pos

            for (dx, dy) in [(0, 1), (0, -1), (1, 0), (-1, 0)] {
                let new_x = x + dx
                let new_y = y + dy
                if 0 <= new_x && new_x < BOARD_SIZE.get(0) && 0 <= new_y && new_y < BOARD_SIZE.get(1) {
                    if !contains(visited, (new_x, new_y)) && board.get(new_x).get(new_y) == board.get(x).get(y) {
                        stack.add((new_x, new_y))
                    }
                }
            }
        }
        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        board.get(x1).set(y1, " ")
        board.get(x2).set(y2, " ")
    }

    public func is_game_over(): Bool {
        for (row in board) {
            for (icon in row) {
                if icon != " " {
                    return false
                }
            }
        }
        return true
    }
}

class Manacher {

    let input_string: String

    public init(input_string: String) {
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        if ((center - diff == -1) or (center + diff == len(string)) or (string[center - diff] != string[center + diff])) {
            return 0
        }
        return 1 + this.palindromic_length(center, diff + 1, string)
    }

    public func palindromic_string(): String {
        let max_length: Int64 = 0
        let new_input_string: String = ""
        let output_string: String = ""

        for i in this.input_string[..len(this.input_string) - 1] {
            new_input_string += i + "|"
        }
        new_input_string += this.input_string[-1]

        for i in 0..len(new_input_string) {
            let length: Int64 = this.palindromic_length(i, 1, new_input_string)

            if (max_length < length) {
                max_length = length
                let start: Int64 = i
            }
        }

        for i in new_input_string[start - max_length..start + max_length + 1] {
            if (i != "|") {
                output_string += i
            }
        }

        return output_string
    }
}

import std.collection.ArrayList
import std.math.abs

class MetricsCalculator {

    var true_positives: Int64
    var false_positives: Int64
    var false_negatives: Int64
    var true_negatives: Int64

    public init() {
        this.true_positives = 0
        this.false_positives = 0
        this.false_negatives = 0
        this.true_negatives = 0
    }

    public func update(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Unit {
        for (var i = 0; i < predicted_labels.size(); i = i + 1) {
            var predicted = predicted_labels.get(i)
            var true_label = true_labels.get(i)
            if (predicted == 1 and true_label == 1) {
                this.true_positives = this.true_positives + 1
            } elif (predicted == 1 and true_label == 0) {
                this.false_positives = this.false_positives + 1
            } elif (predicted == 0 and true_label == 1) {
                this.false_negatives = this.false_negatives + 1
            } elif (predicted == 0 and true_label == 0) {
                this.true_negatives = this.true_negatives + 1
            }
        }
    }

    public func precision(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        var denominator = this.true_positives + this.false_positives
        if (denominator == 0) {
            return 0.0
        }
        return this.true_positives.to_float64() / denominator.to_float64()
    }

    public func recall(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        var denominator = this.true_positives + this.false_negatives
        if (denominator == 0) {
            return 0.0
        }
        return this.true_positives.to_float64() / denominator.to_float64()
    }

    public func f1_score(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        var prec = this.precision(predicted_labels, true_labels)
        var rec = this.recall(predicted_labels, true_labels)
        if (prec + rec == 0.0) {
            return 0.0
        }
        return (2 * prec * rec) / (prec + rec)
    }

    public func accuracy(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        var total = this.true_positives + this.false_positives + this.false_negatives + this.true_negatives
        if (total == 0) {
            return 0.0
        }
        return (this.true_positives + this.true_negatives).to_float64() / total.to_float64()
    }
}

