                    let sum = 0.0
                    for i in 0..right_ranking_list.size() {
                        sum += right_ranking_list[i] * ranking_array[i]
                    }
                    let ap = sum / total_num
                    separate_result.add(ap)
                }
            }
            let sum = 0.0
            for r in separate_result {
                sum += r
            }
            return sum / separate_result.size(), separate_result
        }
    }
}

import std.collection.ArrayList
import std.random.Random
import std.convert.Parsable

class MinesweeperGame {

    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        let arr = ArrayList<ArrayList<String>>()
        for i in 0..<n {
            let row = ArrayList<String>()
            for j in 0..<n {
                row.add("0")
            }
            arr.add(row)
        }

        let rnd = Random()
        for num in 0..<k {
            let x = rnd.next(n)
            let y = rnd.next(n)
            arr.get(y).set(x, "X")

            if (x >= 0 && x <= n-2) && (y >= 0 && y <= n-1) {
                if arr.get(y).get(x+1) != "X" {
                    let val = Int64.parse(arr.get(y).get(x+1)) + 1
                    arr.get(y).set(x+1, val.to_string())
                }
            }

            if (x >= 1 && x <= n-1) && (y >= 0 && y <= n-1) {
                if arr.get(y).get(x-1) != "X" {
                    let val = Int64.parse(arr.get(y).get(x-1)) + 1
                    arr.get(y).set(x-1, val.to_string())
                }
            }

            if (x >= 1 && x <= n-1) && (y >= 1 && y <= n-1) {
                if arr.get(y-1).get(x-1) != "X" {
                    let val = Int64.parse(arr.get(y-1).get(x-1)) + 1
                    arr.get(y-1).set(x-1, val.to_string())
                }
            }

            if (x >= 0 && x <= n-2) && (y >= 1 && y <= n-1) {
                if arr.get(y-1).get(x+1) != "X" {
                    let val = Int64.parse(arr.get(y-1).get(x+1)) + 1
                    arr.get(y-1).set(x+1, val.to_string())
                }
            }

            if (x >= 0 && x <= n-1) && (y >= 1 && y <= n-1) {
                if arr.get(y-1).get(x) != "X" {
                    let val = Int64.parse(arr.get(y-1).get(x)) + 1
                    arr.get(y-1).set(x, val.to_string())
                }
            }

            if (x >= 0 && x <= n-2) && (y >= 0 && y <= n-2) {
                if arr.get(y+1).get(x+1) != "X" {
                    let val = Int64.parse(arr.get(y+1).get(x+1)) + 1
                    arr.get(y+1).set(x+1, val.to_string())
                }
            }

            if (x >= 1 && x <= n-1) && (y >= 0 && y <= n-2) {
                if arr.get(y+1).get(x-1) != "X" {
                    let val = Int64.parse(arr.get(y+1).get(x-1)) + 1
                    arr.get(y+1).set(x-1, val.to_string())
                }
            }

            if (x >= 0 && x <= n-1) && (y >= 0 && y <= n-2) {
                if arr.get(y+1).get(x) != "X" {
                    let val = Int64.parse(arr.get(y+1).get(x)) + 1
                    arr.get(y+1).set(x, val.to_string())
                }
            }
        }
        return arr
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        let arr = ArrayList<ArrayList<String>>()
        for i in 0..<n {
            let row = ArrayList<String>()
            for j in 0..<n {
                row.add("-")
            }
            arr.add(row)
        }
        return arr
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for i in 0..<n {
            for j in 0..<n {
                if map.get(i).get(j) == "-" && minesweeper_map.get(i).get(j) != "X" {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if minesweeper_map.get(x).get(y) == "X" {
            return false
        } else {
            player_map.get(x).set(y, minesweeper_map.get(x).get(y))
            score += 1
            if check_won(player_map) {
                return true
            }
            return player_map
        }
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.time.DateTime
import std.math.abs

class MovieBookingSystem {

    let movies: ArrayList<HashMap<String, Any>>

    public init() {
        movies = ArrayList<HashMap<String, Any>>()
    }

    public func add_movie(name: String, price: Float64, start_time: String, end_time: String, n: Int64): Unit {
        let seats = ArrayList<ArrayList<Int64>>()
        for i in 0..n {
            let row = ArrayList<Int64>()
            for j in 0..n {
                row.append(0)
            }
            seats.append(row)
        }
        let movie = HashMap<String, Any>()
        movie.put("name", name)
        movie.put("price", price)
        movie.put("start_time", DateTime.parse(start_time, "yyyy/MM/dd HH:mm"))
        movie.put("end_time", DateTime.parse(end_time, "yyyy/MM/dd HH:mm"))
        movie.put("seats", seats)
        movies.append(movie)
    }

    public func book_ticket(name: String, seats_to_book: ArrayList<ArrayList<Int64>>): String {
        for movie in movies {
            if movie.get("name") == name {
                let seats = movie.get("seats") as ArrayList<ArrayList<Int64>>
                for seat in seats_to_book {
                    let row = seat.get(0)
                    let col = seat.get(1)
                    if (seats.get(row) as ArrayList<Int64>).get(col) == 1 {
                        return "Booking failed."
                    }
                }
                for seat in seats_to_book {
                    let row = seat.get(0)
                    let col = seat.get(1)
                    (seats.get(row) as ArrayList<Int64>).set(col, 1)
                }
                return "Booking success."
            }
        }
        return "Movie not found."
    }

    public func available_movies(start_time: String, end_time: String): ArrayList<String> {
        let available = ArrayList<String>()
        let start = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let end = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")
        for movie in movies {
            let movie_start = movie.get("start_time") as DateTime
            let movie_end = movie.get("end_time") as DateTime
            if start <= movie_start and movie_end <= end {
                available.append(movie.get("name") as String)
            }
        }
        return available
    }
}

import std.random.Random
import std.collection.ArrayList

class MusicPlayer {

    var playlist: ArrayList<String>
    var current_song: Option<String>
    var volume: Int64

    public init() {
        this.playlist = ArrayList<String>()
        this.current_song = None
        this.volume = 50
    }

    public func add_song(song: String): Unit {
        this.playlist.add(song)
    }

    public func remove_song(song: String): Unit {
        if (this.playlist.contains(song)) {
            this.playlist.remove(song)
            if (this.current_song == Some(song)) {
                this.stop()
            }
        }
    }

    public func play(): Option<String> {
        if (this.playlist.size() > 0 and this.current_song != None) {
            return this.playlist.get(0)
        } elif (this.playlist.size() > 0) {
            return Some(this.playlist.get(0))
        } else {
            return None
        }
    }

    public func stop(): Bool {
        if (this.current_song != None) {
            this.current_song = None
            return true
        } else {
            return false
        }
    }

    public func switch_song(): Bool {
        if (this.current_song != None) {
            var current_index = this.playlist.index_of(this.current_song.unwrap())
            if (current_index < this.playlist.size() - 1) {
                this.current_song = Some(this.playlist.get(current_index + 1))
                return true
            } else {
                return false
            }
        } else {
            return false
        }
    }

    public func previous_song(): Bool {
        if (this.current_song != None) {
            var current_index = this.playlist.index_of(this.current_song.unwrap())
            if (current_index > 0) {
                this.current_song = Some(this.playlist.get(current_index - 1))
                return true
            } else {
                return false
            }
        } else {
            return false
        }
    }

    public func set_volume(volume: Int64): Bool {
        if (volume >= 0 and volume <= 100) {
            this.volume = volume
            return true
        } else {
            return false
        }
    }

    public func shuffle(): Bool {
        if (this.playlist.size() > 0) {
            Random.shuffle(this.playlist)
            return true
        } else {
            return false
        }
    }
}

import std.collection.ArrayList

class NLPDataProcessor {

    public func construct_stop_word_list(): ArrayList<String> {
        let stop_word_list = ArrayList<String>()
        stop_word_list.add("a")
        stop_word_list.add("an")
        stop_word_list.add("the")
        return stop_word_list
    }

    public func remove_stop_words(string_list: ArrayList<String>, stop_word_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let answer = ArrayList<ArrayList<String>>()
        for string in string_list {
            let string_split = string.split(" ")
            let filtered_words = ArrayList<String>()
            for word in string_split {
                if not stop_word_list.contains(word) {
                    filtered_words.add(word)
                }
            }
            answer.add(filtered_words)
        }
        return answer
    }

    public func process(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let stop_word_list = self.construct_stop_word_list()
        let words_list = self.remove_stop_words(string_list, stop_word_list)
        return words_list
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let words_list = ArrayList<ArrayList<String>>()
        let pattern = Regex("[^a-zA-Z\\s]")
        for string in string_list {
            let processed_string = pattern.replace_all(string.lower(), "")
            let words = processed_string.split(" ")
            words_list.add(words)
        }
        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        let word_frequency = HashMap<String, Int64>()
        for words in words_list {
            for word in words {
                if word_frequency.contains_key(word) {
                    word_frequency.set(word, word_frequency.get(word) + 1)
                } else {
                    word_frequency.set(word, 1)
                }
            }
        }
        let sorted_word_frequency = word_frequency.to_list().sort_by(|a, b| b.1.compare(&a.1))
        let top_5_word_frequency = HashMap<String, Int64>()
        for i in 0..min(5, sorted_word_frequency.size()) {
            let entry = sorted_word_frequency.get(i)
            top_5_word_frequency.set(entry.0, entry.1)
        }
        return top_5_word_frequency
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let words_list = self.process_data(string_list)
        let word_frequency_dict = self.calculate_word_frequency(words_list)
        return word_frequency_dict
    }
}

