import std.convert.Parsable
import std.unicode.UnicodeStringExtension

class NumberWordFormatter {

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "TWO", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match x {
            case Some(val) => return this.format_string(val)
            case None => return ""
        }
    }

    public func format_string(x: String): String {
        let parts = x.split(".")
        let lstr = parts.get_or_else(0, "")
        let rstr = parts.get_or_else(1, "")
        let lstrrev = lstr.reverse()
        let mut a = Array::repeat(5, "")

        if lstrrev.length() % 3 == 1 {
            lstrrev += "00"
        } elif lstrrev.length() % 3 == 2 {
            lstrrev += "0"
        }

        let mut lm = ""
        for i in 0..(lstrrev.length() / 3) {
            let chunk = lstrrev.substr(i * 3, 3).reverse()
            a[i] = chunk
            if chunk != "000" {
                lm = this.trans_three(chunk) + " " + this.parse_more(i as Int64) + " " + lm
            } else {
                lm += this.trans_three(chunk)
            }
        }

        let xs = if rstr != "" { "AND CENTS " + this.trans_two(rstr) + " " } else { "" }
        if lm.trim() == "" {
            "ZERO ONLY"
        } else {
            lm.trim() + " " + xs + "ONLY"
        }
    }

    public func trans_two(s: String): String {
        let s = s.pad_left(2, '0')
        match s[0] {
            '0' => this.NUMBER[s[1].to_int().unwrap()],
            '1' => this.NUMBER_TEEN[s.to_int().unwrap() - 10],
            _ => match s[1] {
                '0' => this.NUMBER_TEN[s[0].to_int().unwrap() - 1],
                _ => this.NUMBER_TEN[s[0].to_int().unwrap() - 1] + " " + this.NUMBER[s[1].to_int().unwrap()]
            }
        }
    }

    public func trans_three(s: String): String {
        match s[0] {
            '0' => this.trans_two(s.substr(1, 2)),
            _ => match s.substr(1, 2) {
                "00" => this.NUMBER[s[0].to_int().unwrap()] + " HUNDRED",
                _ => this.NUMBER[s[0].to_int().unwrap()] + " HUNDRED AND " + this.trans_two(s.substr(1, 2))
            }
        }
    }

    public func parse_more(i: Int64): String {
        this.NUMBER_MORE[i]
    }
}

import std.collection.ArrayList
import std.convert.RadixConvertible

class NumericEntityUnescaper {

    public init() {}

    public func replace(string: String): String {
        let out = ArrayList<Rune>()
        var pos = 0
        let length = string.length()

        while pos < length - 2 {
            if string.charAt(pos) == '&' && string.charAt(pos + 1) == '#' {
                var start = pos + 2
                var is_hex = false
                let first_char = string.charAt(start)

                if first_char == 'x' || first_char == 'X' {
                    start += 1
                    is_hex = true
                }

                if start == length {
                    return String.from_runes(out)
                }

                var end = start
                while end < length && self.is_hex_char(string.charAt(end)) {
                    end += 1
                }

                if end < length && string.charAt(end) == ';' {
                    let entity_str = string.substring(start, end)
                    let radix = is_hex ? 16 : 10
                    let entity_value = RadixConvertible.to_int(entity_str, radix)
                    if entity_value != nil {
                        out.add(Rune(entity_value!))
                        pos = end + 1
                        continue
                    }
                }
            }
            out.add(string.charAt(pos))
            pos += 1
        }

        if pos < length {
            out.add(string.charAt(pos))
        }

        return String.from_runes(out)
    }

    public static func is_hex_char(char: Rune): Bool {
        return char.is_digit() || ('a' <= char.to_lower() && char.to_lower() <= 'f')
    }
}

