import std.collection.ArrayList
import std.random.Random

class Snake {

    var length: Int64
    let SCREEN_WIDTH: Int64
    let SCREEN_HEIGHT: Int64
    let BLOCK_SIZE: Int64
    var positions: ArrayList<ArrayList<Int64>>
    var score: Int64
    var food_position: ArrayList<Int64>

    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZE: Int64, food_position: ArrayList<Int64>) {
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.food_position = food_position
    }

    public func move(direction: ArrayList<Int64>): Unit {
        let cur = this.positions.get(0)
        let x = direction.get(0)
        let y = direction.get(1)

        let new_x = (cur.get(0) + (x * this.BLOCK_SIZE)) % this.SCREEN_WIDTH
        let new_y = (cur.get(1) + (y * this.BLOCK_SIZE)) % this.SCREEN_HEIGHT
        let new = ArrayList<Int64>([new_x, new_y])

        if (new.get(0) == this.food_position.get(0) and new.get(1) == this.food_position.get(1)) {
            this.eat_food()
        }

        if (this.positions.size() > 2 and this.positions.slice(2).contains(new)) {
            this.reset()
        } else {
            this.positions.insert(0, new)
            if (this.positions.size() > this.length) {
                this.positions.remove(this.positions.size() - 1)
            }
        }
    }

    public func random_food_position(): Unit {
        while (this.positions.contains(this.food_position)) {
            let rand_x = Random.next_int(this.SCREEN_WIDTH / this.BLOCK_SIZE) * this.BLOCK_SIZE
            let rand_y = Random.next_int(this.SCREEN_HEIGHT / this.BLOCK_SIZE) * this.BLOCK_SIZE
            this.food_position = ArrayList<Int64>([rand_x, rand_y])
        }
    }

    public func reset(): Unit {
        this.length = 1
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([this.SCREEN_WIDTH / 2, this.SCREEN_HEIGHT / 2])])
        this.score = 0
        this.random_food_position()
    }

    public func eat_food(): Unit {
        this.length += 1
        this.score += 100
        this.random_food_position()
    }
}

import std.collection.ArrayList
import std.regex.Regex
import std.unicode.UnicodeStringExtension

class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        let pattern = "(?<!\\w\\.\\w.)(?<![A-Z][a-z]\\.)(?<=\\.|\\?)\\s"
        let regex = Regex(pattern)
        let sentences = regex.split(sentences_string)
        return ArrayList(sentences)
    }

    public func count_words(sentence: String): Int64 {
        let pattern = "[^a-zA-Z\\s]"
        let regex = Regex(pattern)
        let cleaned_sentence = regex.replace_all(sentence, "")
        let words = cleaned_sentence.split(" ")
        return Int64(words.length())
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = self.split_sentences(sentences_string)
        let max_count = Int64(0)
        for sentence in sentences {
            let count = self.count_words(sentence)
            if count > max_count {
                max_count = count
            }
        }
        return max_count
    }
}

