import std.collection.HashMap
import std.collection.ArrayList

class SQLQueryBuilder {

    public static func select(table: String, columns!: ArrayList<String> = ArrayList<String>(['*']), where_condition!: Option<HashMap<String, String>> = None): String {
        let cols = if columns[0] == '*' then "*" else columns.join(", ")
        let query = "SELECT \(cols) FROM \(table)"
        if where_condition.is_some() {
            let conditions = where_condition.unwrap().map({ (k, v) -> String in "\(k)='\(v)'" }).join(" AND ")
            query.append(" WHERE \(conditions)")
        }
        return query
    }

    public static func insert(table: String, data: HashMap<String, String>): String {
        let keys = data.keys().join(", ")
        let values = data.values().map({ v -> String in "'\(v)'" }).join(", ")
        return "INSERT INTO \(table) (\(keys)) VALUES (\(values))"
    }

    public static func delete(table: String, where_condition!: Option<HashMap<String, String>> = None): String {
        let query = "DELETE FROM \(table)"
        if where_condition.is_some() {
            let conditions = where_condition.unwrap().map({ (k, v) -> String in "\(k)='\(v)'" }).join(" AND ")
            query.append(" WHERE \(conditions)")
        }
        return query
    }

    public static func update(table: String, data: HashMap<String, String>, where_condition!: Option<HashMap<String, String>> = None): String {
        let updates = data.map({ (k, v) -> String in "\(k)='\(v)'" }).join(", ")
        let query = "UPDATE \(table) SET \(updates)"
        if where_condition.is_some() {
            let conditions = where_condition.unwrap().map({ (k, v) -> String in "\(k)='\(v)'" }).join(" AND ")
            query.append(" WHERE \(conditions)")
        }
        return query
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        let sorted_data = data.clone()
        sort(sorted_data)
        let n = sorted_data.size()
        if n % 2 == 1 {
            return sorted_data.get(n // 2).to_float64()
        } else {
            return (sorted_data.get(n // 2 - 1).to_float64() + sorted_data.get(n // 2).to_float64()) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let counts = HashMap<Int64, Int64>()
        for value in data {
            counts.insert(value, counts.get_or_default(value, 0) + 1)
        }
        let max_count = counts.values().max().unwrap_or(0)
        let mode_values = ArrayList<Int64>()
        for (value, count) in counts {
            if count == max_count {
                mode_values.add(value)
            }
        }
        return mode_values
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        let n = x.size()
        if n == 0 || n != y.size() {
            return None
        }
        let mean_x = x.sum().to_float64() / n.to_float64()
        let mean_y = y.sum().to_float64() / n.to_float64()
        let mut numerator = 0.0
        let mut sum_x_sq = 0.0
        let mut sum_y_sq = 0.0
        for i in 0..n {
            let xi = x.get(i).to_float64()
            let yi = y.get(i).to_float64()
            numerator += (xi - mean_x) * (yi - mean_y)
 sum_x_sq += (xi - mean_x).pow(2)
 sum_y_sq += (yi - mean_y).pow(2)
 }
 let denominator = sqrt(sum_x_sq * sum_y_sq)
 if denominator == 0.0 {
 return None
 }
 return Some(numerator / denominator)
 }

 public static func mean(data: ArrayList<Int64>): Option<Float64> {
 let n = data.size()
 if n == 0 {
 return None
 }
 return Some(data.sum().to_float64() / n.to_float64())
 }

 public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
 let mut matrix = ArrayList<ArrayList<Float64>>()
 let cols = data.get(0).size()
 for i in 0..cols {
 let mut row = ArrayList<Float64>()
 for j in 0..cols {
 let mut column1 = ArrayList<Int64>()
 let mut column2 = ArrayList<Int64>()
 for lst in data {
 column1.add(lst.get(i))
 column2.add(lst.get(j))
 }
 let correlation = correlation(column1, column2)
 row.add(correlation.unwrap_or(0.0))
 }
 matrix.add(row)
 }
 return matrix
 }

 public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
 let n = data.size()
 if n < 2 {
 return None
 }
 let mean_value = mean(data).unwrap()
 let mut variance = 0.0
 for x in data {
 variance += (x.to_float64() - mean_value).pow(2)
 }
 variance /= (n - 1).to_float64()
 return Some(sqrt(variance))
 }

 public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
 let mean_val = mean(data)?
 let std_deviation = standard_deviation(data)?
 if std_deviation == 0.0 {
 return None
 }
 let mut z_scores = ArrayList<Float64>()
 for x in data {
 z_scores.add((x.to_float64() - mean_val) / std_deviation)
 }
 return Some(z_scores)
 }
}

