    }

    public func set_target_temperature(temperature: Float64): Unit {
        this.target_temperature = temperature
    }

    public func get_mode(): String {
        return this.mode
    }

    public func set_mode(mode: String): Bool {
        if (mode == "heat" or mode == "cool") {
            this.mode = mode
            return true
        } else {
            return false
        }
    }

    public func auto_set_mode(): Unit {
        if (this.current_temperature < this.target_temperature) {
            this.mode = "heat"
        } else {
            this.mode = "cool"
        }
    }

    public func auto_check_conflict(): Bool {
        if (this.current_temperature > this.target_temperature) {
            if (this.mode == "cool") {
                return true
            } else {
                this.auto_set_mode()
                return false
            }
        } else {
            if (this.mode == "heat") {
                return true
            } else {
                this.auto_set_mode()
                return false
            }
        }
    }

    public func simulate_operation(): Int64 {
        this.auto_set_mode()
        var use_time: Int64 = 0
        if (this.mode == "heat") {
            while (this.current_temperature < this.target_temperature) {
                this.current_temperature += 1
                use_time += 1
            }
        } else {
            while (this.current_temperature > this.target_temperature) {
                this.current_temperature -= 1
                use_time += 1
            }
        }
        return use_time
    }
}

import std.collection.ArrayList

class TicTacToe {

    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(N!: Int64 = 3) {
        this.board = ArrayList<ArrayList<String>>()
        for (_ in 0..3) {
            let row = ArrayList<String>()
            for (_ in 0..N) {
                row.add(' ')
            }
            this.board.add(row)
        }
        this.current_player = 'X'
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if this.board.get(row).get(col) == ' ' {
            this.board.get(row).set(col, this.current_player)
            this.current_player = if this.current_player == 'X' then 'O' else 'X'
            return true
        } else {
            return false
        }
    }

    public func check_winner(): Option<String> {
        for row in this.board {
            if row.get(0) != ' ' and row.get(0) == row.get(1) and row.get(1) == row.get(2) {
                return Some(row.get(0))
            }
        }
        for col in 0..3 {
            if this.board.get(0).get(col) != ' ' and this.board.get(0).get(col) == this.board.get(1).get(col) and this.board.get(1).get(col) == this.board.get(2).get(col) {
                return Some(this.board.get(0).get(col))
            }
        }
        if this.board.get(0).get(0) != ' ' and this.board.get(0).get(0) == this.board.get(1).get(1) and this.board.get(1).get(1) == this.board.get(2).get(2) {
            return Some(this.board.get(0).get(0))
        }
        if this.board.get(0).get(2) != ' ' and this.board.get(0).get(2) == this.board.get(1).get(1) and this.board.get(1).get(1) == this.board.get(2).get(0) {
            return Some(this.board.get(0).get(2))
        }
        return None
    }

    public func is_board_full(): Bool {
        for row in this.board {
            for cell in row {
                if cell == ' ' {
                    return false
                }
            }
        }
        return true
    }
}

