import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs

class TriCalculator {

    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        return round(self.taylor(x, 50), 10)
    }

    public func factorial(a: Int64): Decimal {
        let b = Decimal(1)
        var c = a
        while c != 1 {
            b *= Decimal(c)
            c -= 1
        }
        return b
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        var a = Float64(1)
        let x_rad = x / 180 * self.PI
        var count = Int64(1)
        for k in range(1, n) {
            if count % 2 != 0 {
                a -= (x_rad ** (2 * k)) / self.factorial(2 * k).toFloat64()
            } else {
                a += (x_rad ** (2 * k)) / self.factorial(2 * k).toFloat64()
            }
            count += 1
        }
        return a
    }

    public func sin(x: Float64): Float64 {
        let x_rad = x / 180 * self.PI
        var g = Float64(0)
        var t = x_rad
        var n = Int64(1)
        while abs(t) >= 1e-15 {
            g += t
            n += 1
            t = -t * x_rad * x_rad / (2 * n - 1) / (2 * n - 2)
        }
        return round(g, 10)
    }

    public func tan(x: Float64): Option<Float64> {
        let cos_val = self.cos(x)
        if abs(cos_val) > 0.000001 {
            return Some(self.sin(x) / cos_val)
        } else {
            return None
        }
    }
}

