class URLHandler {

    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let scheme_end = this.url.find("://")
        if scheme_end != -1 {
            return Some(this.url[..scheme_end])
        }
        return None
    }

    public func get_host(): Option<String> {
        let scheme_end = this.url.find("://")
        if scheme_end != -1 {
            let url_without_scheme = this.url[scheme_end + 3..]
            let host_end = url_without_scheme.find("/")
            if host_end != -1 {
                return Some(url_without_scheme[..host_end])
            }
            return Some(url_without_scheme)
        }
        return None
    }

    public func get_path(): Option<String> {
        let scheme_end = this.url.find("://")
        if scheme_end != -1 {
            let url_without_scheme = this.url[scheme_end + 3..]
            let host_end = url_without_scheme.find("/")
            if host_end != -1 {
                return Some(url_without_scheme[host_end..])
            }
        }
        return None
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let query_start = this.url.find("?")
        let fragment_start = this.url.find("#")
        if query_start != -1 {
            let query_string = if fragment_start != -1 {
                this.url[query_start + 1..fragment_start]
            } else {
                this.url[query_start + 1..]
            }
            let mut params = HashMap<String, String>::new()
            if query_string.len() > 0 {
                let param_pairs = query_string.split("&")
                for pair in param_pairs {
                    let key_value = pair.split("=")
                    if key_value.len() == 2 {
                        let key = key_value[0]
                        let value = key_value[1]
                        params.insert(key, value)
                    }
                }
            }
            return Some(params)
        }
        return None
    }

    public func get_fragment(): Option<String> {
        let fragment_start = this.url.find("#")
        if fragment_start != -1 {
            return Some(this.url[fragment_start + 1..])
        }
        return None
    }
}

import std.collection.ArrayList

class UrlPath {

    /*
    The  class is a utility for encapsulating and manipulating the path component of a URL, including adding nodes, parsing path strings, and building path strings with optional encoding.
    */

    let segments: ArrayList<String>
    var with_end_tag: Bool

    public init() {
        /*
        Initializes the UrlPath object with an empty list of segments and a flag indicating the presence of an end tag.
        */
        this.segments = ArrayList<String>()
        this.with_end_tag = false
    }

    public func add(segment: String): Unit {
        /*
        Adds a segment to the list of segments in the UrlPath.
        :param segment: String, the segment to add.
        >>> url_path = UrlPath()
        >>> url_path.add('foo')
        >>> url_path.add('bar')

        url_path.segments = ['foo', 'bar']
        */
        this.segments.add(this.fix_path(segment))
    }

    public func parse(path: String): Unit {
        /*
        Parses a given path string and populates the list of segments in the UrlPath.
        :param path: String,thead path string to parse.
        >>> url_path = UrlPath()
        >>> url_path.parse('/foo/bar/')

        url_path.segments = ['foo', 'bar']
        */
        if path.size() > 0 {
            if path.ends_with("/") {
                this.with_end_tag = true
            }
            let fixed_path = this.fix_path(path)
            if fixed_path.size() > 0 {
                let split = fixed_path.split("/")
                for seg in split {
                    this.segments.add(seg)
                }
            }
        }
    }

    public static func fix_path(path: String): String {
        /*
        Fixes the given path string by removing leading and trailing slashes.
        :param path: String, the path string to fix.
        :return: String, the fixed path string.
        >>> url_path = UrlPath()
        >>> url_path.fix_path('/foo/bar/')
        'foo/bar'

        */
        if path.size() == 0 {
            return ""
        }
        return path.strip("/")
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        let norm_1 = 0.0
        let norm_2 = 0.0
        let dot_product = 0.0

        for i in 0..vector_1.size() {
            norm_1 += pow(vector_1.get(i), 2)
            norm_2 += pow(vector_2.get(i), 2)
            dot_product += vector_1.get(i) * vector_2.get(i)
        }

        norm_1 = sqrt(norm_1)
        norm_2 = sqrt(norm_2)
        return dot_product / (norm_1 * norm_2)
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let norm_1 = 0.0
        for val in vector_1 {
            norm_1 += pow(val, 2)
        }
        norm_1 = sqrt(norm_1)

        let all_norms = ArrayList<Float64>()
        let dot_products = ArrayList<Float64>()

        for vec in vectors_all {
            let norm = 0.0
            let dot_product = 0.0
            for i in 0..vec.size() {
                norm += pow(vec.get(i), 2)
                dot_product += vec.get(i) * vector_1.get(i)
            }
            all_norms.add(sqrt(norm))
            dot_products.add(dot_product)
        }

        let similarities = ArrayList<Float64>()
        for i in 0..dot_products.size() {
            similarities.add(dot_products.get(i) / (norm_1 * all_norms.get(i)))
        }
        return similarities
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        if vector_list_1.size() == 0 or vector_list_2.size() == 0 {
            raise ZeroDivisionError('At least one of the passed list is empty.')
        }

        let mean_1 = ArrayList<Float64>()
        for i in 0..vector_list_1.get(0).size() {
            let sum = 0.0
            for vec in vector_list_1 {
                sum += vec.get(i)
            }
            mean_1.add(sum / vector_list_1.size())
        }

        let mean_2 = ArrayList<Float64>()
        for i in 0..vector_list_2.get(0).size() {
            let sum = 0.0
            for vec in vector_list_2 {
                sum += vec.get(i)
            }
            mean_2.add(sum / vector_list_2.size())
        }

        return VectorUtil.similarity(mean_1, mean_2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result = HashMap<String, Float64>()
        for key in number_dict.keys() {
            let count = number_dict.get(key)
            let w = log((total_num + 1) / (count + 1))
            result.put(key, w)
        }
        return result
    }
}

